<script setup lang="ts">
import { computed, ref } from 'vue'
import { current, db, month, navigate, currentOpenDays, openImport } from '../store'
import { daysInMonth, monthNow, prettyMonth, weekday } from '../domain/dates'
import { activeOn, effectiveCell, orderedEmployees } from '../domain/model'
import { summary } from '../domain/statistics'
import { coverage, validate } from '../domain/validation'
import Icon from '../components/Icon.vue'
import ShiftTag from '../components/ShiftTag.vue'
import FirstUseSetup from '../components/FirstUseSetup.vue'
import GenerateDialog from '../components/GenerateDialog.vue'
import MonthBar from '../components/MonthBar.vue'
const showGenerate = ref(false)
const hasSchedule = computed(() => !!current.value?.run || Object.values(current.value?.cells || {}).some(c => c.kind === 'shift'))
const stats = computed(() => current.value ? summary(db.value, current.value) : undefined)
const issues = computed(() => current.value ? validate(db.value, current.value) : [])
const employees = computed(() => orderedEmployees(db.value).filter(e => daysInMonth(month.value).some(d => activeOn(e, d))))
const previewDays = computed(() => daysInMonth(month.value).slice(0, 8))
const cov = computed(() => current.value ? coverage(db.value, current.value) : [])
const percent = (n: number | null | undefined) => n == null ? '—' : `${Math.round(n * 100)}%`
</script>
<template><section class="page-heading"><div><div class="title-context">你好，管理员<span class="greeting-line"></span>新的安排，从这里开始</div><h1>工作台</h1><p>切换月份查看进度，让每一次轮转都有依据。</p></div><button class="button primary" @click="showGenerate = true"><Icon name="sparkle" :size="17" />{{ hasSchedule ? '生成下月排班' : '生成本月排班' }}</button></section><section class="panel overview-month"><MonthBar><div class="month-bar-end"><span class="muted">统计与预览均对应所选月份</span><button class="button secondary small-button" :disabled="month === monthNow()" @click="month = monthNow()">回到本月</button></div></MonthBar></section><FirstUseSetup v-if="!db.demo && (!db.employees.length || !hasSchedule)" @generate="showGenerate = true" />
  <section class="metric-strip"><div><span><Icon name="users" :size="17" />在册员工</span><strong>{{ employees.length }}<small>人</small></strong><p>动态配对，同班同房间</p></div><div><span><Icon name="calendar" :size="17" />所选月开班</span><strong>{{ currentOpenDays }}<small>天</small></strong><p>周末默认休息，调休可修改</p></div><div><span><Icon name="check" :size="17" />班次成组达标</span><strong>{{ percent(stats?.paired) }}</strong><p>每个启用班次恰好2人</p></div><div><span><Icon name="warning" :size="17" />待处理冲突</span><strong :class="{ 'text-amber': issues.some(i => i.level === 'error') }">{{ issues.filter(i => i.level === 'error').length }}<small>项</small></strong><p>{{ stats?.gap || 0 }}个人天缺口需要核对</p></div></section>
  <div class="dashboard-grid"><section class="panel schedule-preview"><header class="panel-header"><div><h2>{{ prettyMonth(month) }}排班一览<span class="pill">{{ !current ? '未生成' : current.status === 'confirmed' ? '已确认' : '草稿' }}</span></h2><p>房间用颜色区分，班次一眼可见。</p></div><button class="text-button" @click="navigate('schedule')">查看完整排班<Icon name="arrow" :size="16" /></button></header><div v-if="current" class="table-scroll"><table class="preview-table"><thead><tr><th>员工</th><th v-for="date in previewDays" :key="date"><span>{{ Number(date.slice(8)) }}</span><small>周{{ weekday(date) }}</small></th></tr></thead><tbody><tr v-for="employee in employees.slice(0, 7)" :key="employee.id"><th><span class="employee-dot">{{ employee.name.slice(-1) }}</span>{{ employee.name }}</th><td v-for="date in previewDays" :key="date"><ShiftTag :cell="effectiveCell(db, current, employee, date)" /></td></tr></tbody></table></div><div v-else class="empty-state compact"><Icon name="calendar" :size="34" /><h3>这个月，还没有班表</h3><p>导入或新增员工后即可生成；上月班表可选。</p><button class="button secondary" @click="navigate('schedule')">开始排班</button></div><footer class="panel-footer"><div class="legend"><span v-for="room in db.rooms" :key="room.id"><i :style="{ background: room.color, border: room.id === 'photon' ? '1px solid #cbd4ce' : undefined }"></i>{{ room.name }}</span><span><i class="rest-legend"></i>休息</span><span><i class="vacation-legend"></i>预定休假</span><span><i class="leave-legend"></i>事后请假</span></div></footer></section>
    <section class="panel monthly-progress"><header class="panel-header"><div><h2>月度检查</h2><p>先看覆盖，再看轮转。</p></div><span class="soft-icon"><Icon name="shield" /></span></header><div class="progress-number"><span>人数覆盖率</span><strong>{{ percent(stats?.coverage) }}</strong></div><div class="progress-track"><span :style="{ width: percent(stats?.coverage === null ? 0 : stats?.coverage || 0) }"></span></div><div class="checklist"><div><span><i class="check-circle"><Icon name="check" :size="11" /></i>休息、休假与请假保护</span><strong>已启用</strong></div><div><span><i class="check-circle"><Icon name="check" :size="11" /></i>动态两人配对</span><strong>8类班次</strong></div><div><span><i class="check-circle"><Icon name="clock" :size="11" /></i>早晚班完整段目标</span><strong>{{ issues.filter(i => i.rule === 'P01').length }}人待核对</strong></div></div><button class="button secondary full-width" @click="navigate('statistics')">查看统计与异常<Icon name="arrow" :size="16" /></button><p class="fineprint">人数覆盖不等于完整成组。存在硬冲突时，班表只能保留为草稿。</p></section></div>
  <div class="dashboard-grid bottom-grid"><section class="panel"><header class="panel-header"><div><h2>四个房间，一目了然</h2><p>按所选月份当前版本汇总实际安排。</p></div><button class="text-button" @click="navigate('shifts')">管理班次<Icon name="right" :size="15" /></button></header><div class="room-summary-grid"><article v-for="room in db.rooms" :key="room.id" class="room-summary"><span class="room-mark" :style="{ background: room.color, color: room.ink }"><Icon :name="room.id === 'photon' ? 'sparkle' : 'rooms'" :size="19" /></span><h3>{{ room.name }}</h3><p>{{ db.shifts.filter(s => s.roomId === room.id).map(s => `${s.category}班`).join(' / ') }}</p><strong>{{ cov.filter(r => db.shifts.find(s => s.id === r.shiftId)?.roomId === room.id).reduce((n, r) => n + r.actual, 0) }}<small> 人天</small></strong></article></div></section><section class="panel quick-panel"><header class="panel-header"><div><h2>常用操作</h2><p>资料维护与数据流转。</p></div></header><button class="quick-action" @click="openImport('history')"><span class="soft-icon"><Icon name="upload" :size="19" /></span><span><strong>导入上月Excel</strong><small>识别颜色与班次，预览后写入</small></span><Icon name="right" :size="17" /></button><button class="quick-action" @click="navigate('calendar')"><span class="soft-icon"><Icon name="calendar" :size="19" /></span><span><strong>调整休假与调休</strong><small>保护每一个不可用日期</small></span><Icon name="right" :size="17" /></button><button class="quick-action" @click="navigate('employees')"><span class="soft-icon"><Icon name="users" :size="19" /></span><span><strong>维护员工名单</strong><small>员工顺序决定个人目标优先级</small></span><Icon name="right" :size="17" /></button></section></div><GenerateDialog :open="showGenerate" :next="hasSchedule" @close="showGenerate = false" />
</template>
